// Source of truth for the PaperRoute launch video copy in the product workspace.
// is GENERATED by this script; edit copy here, never in the JSON (it gets clobbered).
// Telemetry is pulled from props/paperroute-demo.json so the demo act never drifts.
import {readFileSync, mkdirSync, writeFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
import {dirname, join} from 'node:path';
import {projectArg, resolveWorkspace} from './lib/workspace.mjs';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const argv = process.argv.slice(2);
const workspace = resolveWorkspace(root, {brand: 'paperroute', project: projectArg(argv)});
const demo = JSON.parse(readFileSync(join(workspace.propsDir, 'paperroute-demo.json'), 'utf8'));

const launch = {
  brandId: 'paperroute',
  kicker: 'paperroute.gg',
  headline: 'Put the idle corner to work.',
  demo: {video: demo.video, telemetry: demo.telemetry},
  features: [
    {
      screenshot: 'paperroute/measured.png',
      heading: 'Measured, not estimated',
      lines: [
        'One sponsor in the corner nobody was using',
        'Counts only what is actually on screen',
        'Only while you are at the machine',
      ],
    },
    {
      screenshot: 'paperroute/ledger.png',
      heading: 'An auditable 50/50 ledger',
      lines: [
        'You keep half. The split is fixed.',
        'Balance is a sum of append-only entries',
        'Every constant is public at paperroute.gg/transparency',
      ],
    },
  ],
  cta: 'Measure it at paperroute.gg',
  assets: {
    logoSequence: 'paperroute/logo-reveal',
    logoFrames: 90,
    loopSequence: null,
    loopFrames: 1,
  },
};

mkdirSync(workspace.propsDir, {recursive: true});
const outPath = join(workspace.propsDir, 'paperroute-launch.json');
writeFileSync(outPath, JSON.stringify(launch, null, 2) + '\n');
console.log(`wrote ${outPath}`);
